// src/pages/SDM.jsx
import React, { useState, useEffect, useRef } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import { useUI } from "../context/UIContext";
import Button from "../components/common/Button";
import Card from "../components/common/Card";
import * as sdmData from "../constants/sdm";
import styles from "../SDM.module.css";

import eveVideo from "../assets/eve_sdm_talk.mp4";

const SDM = () => {
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const { setHeroData } = useUI();
  const videoRef = useRef(null);

  const step = searchParams.get("step") || "SELECT";
  const topicParam = searchParams.get("topic") || "";

  const [isPlaying, setIsPlaying] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [selectedTopicId, setSelectedTopicId] = useState(topicParam);

  // 🌟 核心：確保這裡定義了 handleTogglePlay
  const handleTogglePlay = (e) => {
    e.stopPropagation();
    if (!isPlaying) {
      setIsPlaying(true);
      if (videoRef.current) videoRef.current.play();
    } else {
      setIsPaused(!isPaused);
      if (videoRef.current) {
        isPaused ? videoRef.current.play() : videoRef.current.pause();
      }
    }
  };

  const handleConfirmTopic = () => {
    if (!selectedTopicId) return alert("請先選擇主題");
    setSearchParams({ step: "INTRO", topic: selectedTopicId });
  };

  const localTopicList = [
    {
      id: "dcis",
      title: "乳房原位癌",
      description: "適用於診斷為乳房原位癌的病人。",
    },
    {
      id: "bctsm",
      title: "乳癌手術",
      description: "適用於診斷為乳房原位癌或乳癌的病人。",
    },
  ];

  useEffect(() => {
    setHeroData(null);
  }, [setHeroData]);

  return (
    <div className={styles.pageContainer}>
      <div className={styles.interactiveCard}>
        <div className={styles.videoSection}>
          <video
            ref={videoRef}
            src={eveVideo}
            playsInline
            className={styles.theatreVideo}
          />
          {/* 這裡現在一定找得到 handleTogglePlay */}
          <button
            className={styles.controlBtnTopRight}
            onClick={handleTogglePlay}
          >
            {isPlaying && !isPaused ? "⏸ 暫停" : "▶️ 播放"}
          </button>
        </div>

        <div className={styles.contentSection}>
          {step === "SELECT" ? (
            <div>
              {localTopicList.map((item) => (
                <Card
                  key={item.id}
                  title={item.title}
                  description={item.description}
                  isActive={selectedTopicId === item.id}
                  onClick={() => setSelectedTopicId(item.id)}
                />
              ))}
              <Button onClick={handleConfirmTopic} fullWidth>
                確認選擇 ➔
              </Button>
            </div>
          ) : (
            <div>
              <p>詳細內容頁面...</p>
              <Button
                variant="outline"
                onClick={() => setSearchParams({ step: "SELECT" })}
                fullWidth
              >
                返回
              </Button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default SDM;
